package com.acrenex.app.activities;
import android.database.Cursor;import android.os.Bundle;import android.widget.LinearLayout;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.utils;
public class RestrictionsActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Restrictions & Encumbrances","Spatial and legal signals attached to the parcel.");String u=getIntent().getStringExtra("ulpin");if(u==null)u="24-GJ-GN-0001-00001";DatabaseManager m=new DatabaseManager(this);add(root,m,"SELECT restriction_type,authority,description,severity,status FROM restrictions WHERE ulpin=?","Planning / spatial restrictions");add(root,m,"SELECT type,institution,amount,status FROM encumbrances WHERE ulpin=?","Encumbrance / mortgage layer");add(root,m,"SELECT zone_type,authority,buffer_meters,impact_level,status FROM environmental_zones WHERE ulpin=?","Environmental screening");utils.setScreenContentView(this, root);}
 private void add(LinearLayout root,DatabaseManager m,String sql,String title){Cursor c=m.getDatabase().rawQuery(sql,new String[]{getIntent().getStringExtra("ulpin")==null?"24-GJ-GN-0001-00001":getIntent().getStringExtra("ulpin")});try{LinearLayout box=utils.column(this);box.addView(utils.text(this,title,18,utils.TEXT,true));if(c.moveToFirst()){do{for(int i=0;i<c.getColumnCount();i++)box.addView(utils.text(this,c.getColumnName(i)+": "+c.getString(i),13,utils.MUTED,false));box.addView(utils.text(this,"",4,utils.MUTED,false));}while(c.moveToNext());}else box.addView(utils.text(this,"No record in demo dataset.",13,utils.MUTED,false));utils.addCard(root,box,this);}finally{c.close();}}
}
